# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::RelayOutboxSource do
  it "marks only the given positions, never another snapshot of the same company and entry" do
    write_mark_row = lambda do |company_id:, entry_id:, version:, generation:|
      OutboxSnapshot.create!(
        id: entry_id, project_id: 50, user_id: 60, work_date: Date.new(2026, 3, 2), duration: 90.0,
        bill_status: "unbilled", review_status: "not_required", locked: false, source: "manual",
        source_metadata: {}, proof_metadata: {}, created_at: Time.utc(2026, 3, 2), updated_at: Time.utc(2026, 3, 2),
        company_id:, version:, generation:
      ).outbox_position
    end

    # Two snapshots of entry 7 in company 5 share (company_id, id) and differ only by position.
    first = write_mark_row.call(company_id: 5, entry_id: 7, version: 1, generation: 1)
    later = write_mark_row.call(company_id: 5, entry_id: 7, version: 2, generation: 2)
    other_company = write_mark_row.call(company_id: 6, entry_id: 7, version: 1, generation: 1)

    source = described_class.new
    source.mark_sent([first])

    remaining = source.unsent_after(0, 10)
    expect(remaining.map { |row| row.fetch("outbox_position") }).to eq([later, other_company])
    expect(remaining.map { |row| row.fetch("entry").fetch("company_id") }).to eq([5, 6])
    expect(OutboxSnapshot.where(outbox_position: [later, other_company]).pluck(:sent_at)).to all(be_nil)
  end
end


RSpec.describe Timekeeping::RelayOutboxSource do
  it "keeps each row's own company_id in its entry when one read spans several companies" do
    write_span_row = lambda do |company_id:, entry_id:|
      OutboxSnapshot.create!(
        id: entry_id, project_id: 50, user_id: 60, work_date: Date.new(2026, 3, 2), duration: 90.0,
        bill_status: "unbilled", review_status: "not_required", locked: false, source: "manual",
        source_metadata: {}, proof_metadata: {}, created_at: Time.utc(2026, 3, 2), updated_at: Time.utc(2026, 3, 2),
        company_id:, version: 1, generation: 1
      ).outbox_position
    end

    positions = [
      write_span_row.call(company_id: 41, entry_id: 1),
      write_span_row.call(company_id: 42, entry_id: 2),
      write_span_row.call(company_id: 41, entry_id: 3)
    ]

    rows = described_class.new.unsent_after(0, 10)

    expect(rows.map { |row| row.fetch("outbox_position") }).to eq(positions)
    expect(rows.map { |row| [row.fetch("entry").fetch("id"), row.fetch("entry").fetch("company_id")] })
      .to eq([[1, 41], [2, 42], [3, 41]])
  end
end

require "json"

RSpec.describe Timekeeping::RelayOutboxSource do
  # "Payloads carry ids, not user names or emails." and "No token is written to a payload or a log line."
  it "returns each unsent row's entry as exactly the contract entry fields with record ids and no name, email or held token" do
    token = "relay-held-token-#{SecureRandom.hex(8)}"
    allow(Timekeeping::Environment).to receive(:service_token).and_return(token)

    now = Time.current
    OutboxSnapshot.insert_all!([
      {
        "id" => 501, "project_id" => 61, "user_id" => 71, "agent_id" => nil, "work_date" => Date.new(2026, 4, 1),
        "duration" => 90.0, "note" => "Design review", "bill_status" => "unbilled", "review_status" => "not_required",
        "locked" => false, "source" => "manual", "source_metadata" => { "client" => "web" }, "external_run_id" => nil,
        "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => { "nested" => { "ref" => 3 } },
        "discarded_at" => nil, "created_at" => now, "updated_at" => now, "company_id" => 11, "version" => 1,
        "generation" => 1
      }
    ])

    rows = described_class.new.unsent_after(0, 10)

    expect(rows.size).to eq(1)
    row = rows.first
    expect(row.keys).to match_array(%w[generation outbox_position entry])
    expect(row["entry"].keys).to match_array(Timekeeping::OutboxFields::ENTRY_FIELDS)
    expect(row["entry"]).to include("id" => 501, "project_id" => 61, "user_id" => 71, "company_id" => 11)
    expect(row["entry"].keys.grep(/name|email|token|sent_at|enqueued_at/)).to be_empty

    serialized = JSON.generate(rows)
    Timekeeping::Config.service_credentials.each do |credential|
      expect(serialized).not_to include(credential)
    end
    expect(serialized).not_to include("@")
  end
end
